ruleToc.chapterList:
-@js:
let tim = Math.floor(Math.random()*601);
sleep(200+tim);
let jsq = java.importScript('https://code.jquery.com/jquery-3.6.0.min.js');
let webjs = String(jsq)+String.raw`
function morechapter2() {
    var btn = $('.chaplist-more');
    var id = $('meta[property="og:url"]').attr('content').match(/https?:\/\/[^\/]+\/([^\/]+)\//)[1];
    $.ajax({
        url: "/morechapter",
        type: "POST",
        async: false, //同步模式
        data: { id: id },
        success: function (data) {
            var ret = JSON.parse(data);
            if (ret.code == "-1") {
                layerMsg(ret.msg);
            } else if (ret.code == "200") {
                res = ret.data;
                for (var a = 0; a < res.length; a++) {
                    var vid = res[a].chapterid;
                    var vidname = res[a].chaptername;
                    var b_sn = '<a href="/' + id + '/' + vid + '.html"><li>' + vidname + '</li></a>';
                    $(".chapterlistload ul").append(b_sn);
                    btn.hide();
                }
                return
            }
            btn.prop('disabled', false);
        },
        error: function (jqXHR, textStatus, errorThrown) {
            layerMsg("出了点小问题，请稍后再试");
            btn.prop('disabled', false);
            btn.html("出了点小问题，请稍后再试");
        }
    });
}
morechapter2();
$('html').html();
`;
